    // Elementos DOM
        const booksGrid = document.getElementById('booksGrid');
        const booksCount = document.getElementById('booksCount');
        const searchInput = document.getElementById('searchInput');
        const searchButton = document.getElementById('searchButton');
        const genreFilter = document.getElementById('genreFilter');
        const yearFilter = document.getElementById('yearFilter');
        const sortFilter = document.getElementById('sortFilter');
        const bookModal = document.getElementById('bookModal');
        const modalContent = document.getElementById('modalContent');
        const closeModal = document.getElementById('closeModal');
        const addBookBtn = document.getElementById('addBookBtn');

        // Estado dos filtros
        let currentFilter = {
            genre: 'all',
            year: 'all',
            sort: 'title',
            search: ''
        };

        // Inicializar a página
        document.addEventListener('DOMContentLoaded', () => {
            renderBooks();
            setupEventListeners();
        });

        // Configurar listeners de eventos
        function setupEventListeners() {
            genreFilter.addEventListener('change', (e) => {
                currentFilter.genre = e.target.value;
                renderBooks();
            });

            yearFilter.addEventListener('change', (e) => {
                currentFilter.year = e.target.value;
                renderBooks();
            });

            sortFilter.addEventListener('change', (e) => {
                currentFilter.sort = e.target.value;
                renderBooks();
            });

            searchButton.addEventListener('click', () => {
                currentFilter.search = searchInput.value.toLowerCase();
                renderBooks();
            });

            searchInput.addEventListener('keyup', (e) => {
                if (e.key === 'Enter') {
                    currentFilter.search = searchInput.value.toLowerCase();
                    renderBooks();
                }
            });

            closeModal.addEventListener('click', () => {
                bookModal.classList.remove('active');
            });

            bookModal.addEventListener('click', (e) => {
                if (e.target === bookModal) {
                    bookModal.classList.remove('active');
                }
            });

        }

        // Filtrar e ordenar livros
        function filterAndSortBooks() {
            let filteredBooks = [...booksData];

            // Aplicar filtro de gênero
            if (currentFilter.genre !== 'all') {
                filteredBooks = filteredBooks.filter(book => book.genre === currentFilter.genre);
            }

            // Aplicar filtro de ano
            if (currentFilter.year !== 'all') {
                filteredBooks = filteredBooks.filter(book => book.year.toString() === currentFilter.year);
            }

            // Aplicar filtro de busca
            if (currentFilter.search) {
                filteredBooks = filteredBooks.filter(book => 
                    book.title.toLowerCase().includes(currentFilter.search) || 
                    book.author.toLowerCase().includes(currentFilter.search) ||
                    book.genreLabel.toLowerCase().includes(currentFilter.search)
                );
            }

            // Ordenar livros
            filteredBooks.sort((a, b) => {
                switch(currentFilter.sort) {
                    case 'title':
                        return a.title.localeCompare(b.title);
                    case 'year':
                        return b.year - a.year;
                    case 'author':
                        return a.author.localeCompare(b.author);
                    default:
                        return 0;
                }
            });

            return filteredBooks;
        }

        // Renderizar livros na grid
        function renderBooks() {
            const filteredBooks = filterAndSortBooks();
            
            booksGrid.innerHTML = '';
            
            filteredBooks.forEach(book => {
                const bookCard = document.createElement('div');
                bookCard.className = 'book-card';
                bookCard.dataset.id = book.id;
                
                const coverContent = book.cover ? 
                    `<img src="${book.cover}" alt="${book.title}" onerror="this.onerror=null; this.src='';">` :
                    `<div class="book-placeholder">
                        <i class="fas fa-book"></i>
                        <p>Capa não disponível</p>
                    </div>`;
                
                bookCard.innerHTML = `
                    <div class="book-cover">
                        ${coverContent}
                    </div>
                    <div class="book-info">
                        <div class="book-title">${book.title}</div>
                        <div class="book-author">${book.author}</div>
                        <div class="book-meta">
                            <div class="book-year">${book.year}</div>
                            <div class="book-genre">${book.genreLabel}</div>
                        </div>
                    </div>
                `;
                
                bookCard.addEventListener('click', () => openBookModal(book.id));
                booksGrid.appendChild(bookCard);
            });
            
            booksCount.textContent = `Exibindo ${filteredBooks.length} publicaç${filteredBooks.length !== 1 ? 'ões' : ''}`;
        }

        // Abrir modal com detalhes do livro
        function openBookModal(bookId) {
        const book = booksData.find(b => b.id === bookId);
    
        if (!book) return;
    
        // Se o livro não tiver uma URL definida, ele usa '#' por padrão
        const downloadLink = book.downloadUrl ? book.downloadUrl : '#';

        modalContent.innerHTML = `
            <div class="modal-book-cover">
                ${book.cover ? `<img src="${book.cover}" alt="${book.title}">` : 
                `<div class="book-placeholder">
                    <i class="fas fa-book"></i>
                    <p>Capa não disponível</p>
                </div>`}
            </div>
        <div class="modal-book-details">
            <h2 class="modal-book-title">${book.title}</h2>
            <h3 class="modal-book-author">${book.author}</h3>
            <p class="modal-book-description">${book.description}</p>
            
            <div class="modal-book-meta">
                <div class="meta-item">
                    <span class="meta-label">Ano de Publicação</span>
                    <span class="meta-value">${book.year}</span>
                </div>
                <div class="meta-item">
                    <span class="meta-label">Gênero</span>
                    <span class="meta-value">${book.genreLabel}</span>
                </div>
                <div class="meta-item">
                    <span class="meta-label">Páginas</span>
                    <span class="meta-value">${book.pages}</span>
                </div>
                <div class="meta-item">
                    <span class="meta-label">Editora</span>
                    <span class="meta-value">${book.publisher}</span>
                </div>
                <div class="meta-item">
                    <span class="meta-label">ISBN</span>
                    <span class="meta-value">${book.isbn}</span>
                </div>
            </div>
            
            <div class="modal-actions">
                <a href="${downloadLink}" target="_blank" class="modal-btn btn-edit" style="text-decoration: none; text-align: center; display: inline-flex; align-items: center; justify-content: center;">
                    <i class="fas fa-download" style="margin-right: 8px;"></i> Baixar
                </a>
                <button class="modal-btn btn-secondary" id="btnModalVoltar">
                    <i class="fas fa-arrow-left" aria-hidden="true"></i> Voltar
                </button>
            </div>
        </div>
    `;
    
    // Ativa o modal na tela
    bookModal.classList.add('active');

    // Funcionalidade do Botão Voltar (fecha o modal)
    document.getElementById('btnModalVoltar').addEventListener('click', () => {
        bookModal.classList.remove('active');
    });
}